// ⚠️ NÃO LOGAR, NÃO PRINTAR EM OUTROS NODES

const clientId = 'f504ae67-15d6-4294-9b6c-01fb4cc71d3d';
const clientSecret = 'ceB3ARNvdBNY3EQdaIPbJuUNOF7A0sKQ';


// Junta no formato exigido pelo HTTP Basic
const raw = `${clientId}:${clientSecret}`;

// Converte para Base64
const base64 = Buffer.from(raw).toString('base64');

return [
  {
    json: {
      basicAuth: `Basic ${base64}`
    }
  }
];

function getNodeData(nodeName) {
  try {
    const node = $(nodeName).first().json;
    return node.body ?? node;
  } catch (error) {
    return null;
  }
}

function parseMoney(value) {
  if (value === null || value === undefined || value === "") return 0;

  if (typeof value === "number") return value;

  let txt = String(value)
    .replace(/R\$/gi, "")
    .replace(/\s+/g, "")
    .trim();

  // Converte formato brasileiro: 1.234,56 -> 1234.56
  if (txt.includes(",")) {
    txt = txt.replace(/\./g, "").replace(",", ".");
  }

  return Number(txt) || 0;
}

function onlyDigits(value) {
  return String(value ?? "").replace(/\D/g, "");
}

function cleanText(value, max = 80) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w\s\-./]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, max);
}

function formatDate(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

// Busca os dados reais da cobrança no node do webhook/origem
const data =
  getNodeData("boleto-vibe") ||
  getNodeData("Switch") ||
  ($input.first().json.body ?? $input.first().json);

const total = parseMoney(
  data.valor_total ??
  data.valor ??
  data.amount ??
  data.total
);

const parcelas = Math.max(1, Number(data.qtd_parcelas || data.parcelas || 1));
const intervalo = Number(data.intervalo || 0);
const inicio = Number(data.inicia_em || 0);

if (!total || total <= 0) {
  throw new Error(
    `valor_total inválido ou zerado. Campos encontrados: ${Object.keys(data).join(", ")}`
  );
}

const hoje = new Date();
const boletos = [];

const base = Math.floor((total / parcelas) * 100) / 100;
let soma = 0;

const idBase = String(
  data.external_reference_id ||
  data.id_pagamento ||
  data.id_int ||
  Date.now()
);

for (let i = 0; i < parcelas; i++) {
  let valor = base;

  if (i === parcelas - 1) {
    valor = Number((total - soma).toFixed(2));
  }

  soma = Number((soma + valor).toFixed(2));

  const vencimento = new Date(hoje);

  if (parcelas === 1) {
    vencimento.setDate(vencimento.getDate() + inicio);
  } else {
    vencimento.setDate(vencimento.getDate() + inicio + intervalo * i);
  }

  const due_date = formatDate(vencimento);
  const parcela = i + 1;

  // Formato: P1_4_12990
  const ref = `P${parcela}${parcelas}${idBase.replace(/\D/g, "").slice(-6)}`.slice(0, 10);

  const instrucaoParcela = cleanText(`Parcela ${parcela}/${parcelas}`, 80);

  const instrucaoDescricao = cleanText(
    data.descricao ||
    data.obs ||
    "Pedido produzido apos confirmacao do pagamento.",
    80
  );

  boletos.push({
    json: {
      id_int: data.external_reference_id || data.id_int || idBase,
      parcela,
      total_parcelas: parcelas,

      external_reference_id: ref,

      amount: valor,
      due_date,

      // C6: cada mensagem de instrucao deve ter no maximo 80 caracteres
      instructions: [
        instrucaoParcela,
        instrucaoDescricao
      ],

      billing_scheme: "15",

      payer: {
        name: cleanText(data.name || data.nome || data.cliente, 100),
        tax_id: onlyDigits(data.documento || data.tax_id || data.cpf_cnpj),
        email: data.email || "",

        address: {
          street: cleanText(data.logradouro || data.endereco || data.street, 100),
          number: String(data.numero || data.number || "0"),
          complement: cleanText(data.complemento || data.complement || "", 50),
          city: cleanText(data.cidade || data.city, 60),
          state: cleanText(data.UF || data.uf || data.state, 2).toUpperCase(),
          zip_code: onlyDigits(data.zip_code || data.cep)
        }
      },

      whats: data.whats || data.whatsapp || ""
    }
  });
}

return boletos;

const items = $input.all();

