  try {
    const node = $(nodeName).first().json;
    return node.body ?? node;
  } catch (error) {
    return {};
  }
}

const origemBoleto = getNodeData("boleto-vibe");
const origemSwitch = getNodeData("Switch");

function limparTexto(texto) {
  if (!texto) return "";
  return texto
    .toString()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function limitar(texto, tamanho) {
  if (!texto) return "";
  return texto.toString().substring(0, tamanho);
}

function normalizarWhats(numero) {
  if (!numero) return "";

  let n = numero.toString().replace(/\D/g, "");
  n = n.replace(/^0+/, "");

  if (!n) return "";
  if (n.startsWith("55")) return n;

  return "55" + n;
}

function toBoolean(valor) {
  if (valor === true) return true;
  if (valor === false) return false;

  if (typeof valor === "string") {
    const v = valor.trim().toLowerCase();
    return v === "true" || v === "1" || v === "sim" || v === "yes";
  }

  if (typeof valor === "number") {
    return valor === 1;
  }

  return false;
}

function ajustarExternalReferenceId(externalReferenceId, isProrrogado, isAvulso) {
  let ref = String(externalReferenceId || "")
    .replace(/[^a-zA-Z0-9]/g, "")
    .trim();

  if (!ref) return "";

  if (ref.startsWith("PR")) {
    ref = "P" + ref.substring(2);
  } else if (ref.startsWith("AV")) {
    ref = "P" + ref.substring(2);
  }

  let prefixo = "";

  if (isProrrogado) {
    prefixo = "PR";
    ref = ref.startsWith("P") ? ref.substring(1) : ref;
  } else if (isAvulso) {
    prefixo = "AV";
    ref = ref.startsWith("P") ? ref.substring(1) : ref;
  } else {
    prefixo = "P";
    ref = ref.startsWith("P") ? ref.substring(1) : ref;
  }

  // C6: somente letras/números e no máximo 10 caracteres
  return `${prefixo}${ref}`.replace(/[^a-zA-Z0-9]/g, "").slice(0, 10);
}

function normalizarInstructions(instructions) {
  if (!Array.isArray(instructions)) return [];

  return instructions
    .map((msg) => limparTexto(msg))
    .filter((msg) => msg)
    .map((msg) => limitar(msg, 80));
}

