  const address = payer.address || {};

  let nome = limparTexto(payer.name);
  let rua = limparTexto(address.street);
  let cidade = limparTexto(address.city);
  let complemento = limparTexto(address.complement || "");
  let estado = (address.state || "").toString().trim().toUpperCase();
  let cep = (address.zip_code || "").toString().replace(/\D/g, "");
  let numero = String(address.number ?? "0").replace(/\D/g, "") || "0";
  let email = (payer.email || "").toString().trim();
  let taxId = (payer.tax_id || "").toString().replace(/\D/g, "");
  let whats = normalizarWhats(
    item.json.whats ||
    item.json.whatsapp ||
    origemBoleto.whats ||
    origemBoleto.whatsapp ||
    ""
  );

  const isProrrogado = toBoolean(
    item.json.is_prorrogado ??
    item.json.body?.is_prorrogado ??
    origemBoleto.is_prorrogado ??
    origemSwitch.is_prorrogado
  );

