    item.json.external_reference_id,
    isProrrogado,
    isAvulso
  );

  nome = limitar(nome, 40);
  rua = limitar(rua, 30);
  cidade = limitar(cidade, 20);
  complemento = limitar(complemento, 20);
  estado = limitar(estado, 2);
  cep = limitar(cep, 8);
  numero = limitar(numero, 10);

  return {
