function limparTexto(texto) {
  if (!texto) return "";
  return texto
    .toString()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function limitar(texto, tamanho) {
  if (!texto) return "";
  return texto.substring(0, tamanho);
}

function normalizarWhats(numero) {
  if (!numero) return "";

  let n = numero.toString().replace(/\D/g, "");
  n = n.replace(/^0+/, "");

  if (n.startsWith("55")) return n;
  return "55" + n;
}

function toBoolean(valor) {
  if (valor === true) return true;
  if (valor === false) return false;

  if (typeof valor === "string") {
    const v = valor.trim().toLowerCase();
    return v === "true" || v === "1" || v === "sim";
  }

  if (typeof valor === "number") {
    return valor === 1;
  }

  return false;
}

function ajustarExternalReferenceId(externalReferenceId, isProrrogado, isAvulso) {
  const ref = (externalReferenceId || "").toString().trim();

  if (!ref) return "";

  // remove prefixos anteriores, se houver
  let base = ref;
  if (base.startsWith("PR")) {
    base = "P" + base.substring(2);
  } else if (base.startsWith("AV")) {
    base = "P" + base.substring(2);
  }

  if (isProrrogado) {
    if (base.startsWith("P")) return "PR" + base.substring(1);
    return "PR" + base;
  }

  if (isAvulso) {
    if (base.startsWith("P")) return "AV" + base.substring(1);
    return "AV" + base;
  }

  return base;
}

